 * Paths are arrays of segments: { k: 'key', v: name } for an object member,
 * or { k: 'idx', v: index } for an array element. joinPath renders them the
 * way both error messages and the `keys` command display a path: keys are
 * dot-joined and an index is appended in brackets with no dot before it.
 */
export function joinPath(parts) {
  let s = ''
  for (const p of parts) {
    if (p.k === 'idx') s += `[${p.v}]`
    else {
      if (s.length) s += '.'
      s += p.v
    }
  }
  return s
}

export function key(name) {
  return { k: 'key', v: name }
}

export function idx(i) {
  return { k: 'idx', v: i }
}

/** Ascending order by Unicode code point, as required for sorted output. */
export function codePointCompare(a, b) {
  const ai = [...a]
  const bi = [...b]
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}
"}

