{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-eFfv1a/src/line-parser.js","content":"import { ConfigError } from './errors.js'
import { joinPath, key, idx } from './path.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_FRAC_RE = /^[+-]?[0-9]+(_[0-9]+)*\.[0-9]+(_[0-9]+)*([eE][+-]?[0-9]+(_[0-9]+)*)?$/
const FLOAT_EXP_RE = /^[+-]?[0-9]+(_[0-9]+)*[eE][+-]?[0-9]+(_[0-9]+)*$/
const BARE_STOP = new Set([' ', '\t', ',', ']', '}'])

function newTable(path, headerDeclared) {
  return { kind: 'table', entries: new Map(), headerDeclared, path }
}

/**
 * Parses one already-known-non-blank line, mutating `root` and returning the
 * table that should become current afterwards (unchanged for assignments).
 */
export class LineParser {
  constructor(line) {
    this.line = line
    this.len = line.length
    this.pos = 0
  }

  ws() {
    while (this.pos < this.len && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) this.pos++
  }

  // True once nothing meaningful remains on the line: end of text, or an
  // unquoted comment marker not glued onto a preceding bare token.
  atEnd() {
    return this.pos >= this.len || this.line[this.pos] === '#' || this.line[this.pos] === ';'
  }

  parseName() {
    this.ws()
    if (this.atEnd()) throw new ConfigError('expected a name')
    const c = this.line[this.pos]
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const start = this.pos
    while (this.pos < this.len && NAME_CHAR.test(this.line[this.pos])) this.pos++
    if (this.pos === start) throw new ConfigError('expected a name')
    return this.line.slice(start, this.pos)
  }

  parseDottedName() {
    const parts = [this.parseName()]
    while (true) {
      this.ws()
      if (this.pos < this.len && this.line[this.pos] === '.') {
        this.pos++
        this.ws()
        parts.push(this.parseName())
      } else break
    }
    return parts
  }

  parseBasicString() {
    this.pos++ // opening quote
    let out = ''
    while (true) {
      if (this.pos >= this.len) throw new ConfigError('unterminated string')
      const c = this.line[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.pos >= this.len) throw new ConfigError('unterminated string')
        const e = this.line[this.pos]
        if (e === '"') { out += '"'; this.pos++ } else if (e === '\\') { out += '\\'; this.pos++ } else if (e === 'n') { out += '\n'; this.pos++ } else if (e === 't') { out += '\t'; this.pos++ } else if (e === 'r') { out += '\r'; this.pos++ } else if (e === '0') { out += '\0'; this.pos++ } else if (e === 'u') {
          this.pos++
          const hex = this.line.slice(this.pos, this.pos + 4)
          if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) throw new ConfigError('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.pos += 4
        } else {
          throw new ConfigError(`invalid escape \\${e}`)
        }
      } else {
        out += c
        this.pos++
      }
    }
  }

  parseLiteralString() {
    this.pos++ // opening quote
    const start = this.pos
    while (true) {
      if (this.pos >= this.len) throw new ConfigError('unterminated string')
      if (this.line[this.pos] === "'") {
        const out = this.line.slice(start, this.pos)
        this.pos++
        return out
      }
      this.pos++
    }
  }

  parseValue(path) {
    this.ws()
    if (this.atEnd() || this.line[this.pos] === ',' || this.line[this.pos] === ']' || this.line[this.pos] === '}') {
      throw new ConfigError('expected a value')
    }
    const c = this.line[this.pos]
    if (c === '"') return { kind: 'string', value: this.parseBasicString() }
    if (c === "'") return { kind: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArrayValue(path)
    if (c === '{') return this.parseInlineTableValue(path)

    const start = this.pos
    while (this.pos < this.len && !BARE_STOP.has(this.line[this.pos])) this.pos++
    const token = this.line.slice(start, this.pos)
    if (token === 'true') return { kind: 'boolean', value: true }
    if (token === 'false') return { kind: 'boolean', value: false }
    if (INT_RE.test(token)) return { kind: 'integer', raw: token }
    if (FLOAT_FRAC_RE.test(token) || FLOAT_EXP_RE.test(token)) return { kind: 'float', raw: token }
    throw new ConfigError(`invalid value ${token}`)
  }

  parseArrayValue(path) {
    this.pos++ // '['
    const items = []
    this.ws()
    if (!this.atEnd() && this.line[this.pos] === ']') {
      this.pos++
      return { kind: 'array', items }
    }
    let i = 0
    while (true) {
      this.ws()
      if (this.atEnd()) throw new ConfigError('unterminated array')
      items.push(this.parseValue(path.concat([idx(i++)])))
      this.ws()
      if (this.atEnd()) throw new ConfigError('unterminated array')
      if (this.line[this.pos] === ',') {
        this.pos++
        this.ws()
        if (!this.atEnd() && this.line[this.pos] === ']') {
          this.pos++
          break
        }
        continue
      } else if (this.line[this.pos] === ']') {
        this.pos++
        break
      } else {
        throw new ConfigError('unterminated array')
      }
    }
    return { kind: 'array', items }
  }

  parseInlineTableValue(path) {
    this.pos++ // '{'
    const table = newTable(path, false)
    this.ws()
    if (!this.atEnd() && this.line[this.pos] === '}') {
      this.pos++
      return table
    }
    while (true) {
      this.ws()
      if (this.atEnd()) throw new ConfigError('unterminated inline table')
      const nameParts = this.parseDottedName()
      this.ws()
      if (this.atEnd() || this.line[this.pos] !== '=') throw new ConfigError('expected = in an inline table')
      this.pos++
      this.assign(table, nameParts)
      this.ws()
      if (this.atEnd()) throw new ConfigError('unterminated inline table')
      if (this.line[this.pos] === ',') {
        this.pos++
        continue
      } else if (this.line[this.pos] === '}') {
        this.pos++
        break
      } else {
        throw new ConfigError('unterminated inline table')
      }
    }
    return table
  }

  // Walks `nameParts` from `table`, creating intermediate tables as needed,
  // and assigns the parsed right-hand-side value at the final segment.
  assign(table, nameParts) {
    let cur = table
    let curPath = table.path
    for (let i = 0; i < nameParts.length - 1; i++) {
      const seg = nameParts[i]
      curPath = curPath.concat([key(seg)])
      const existing = cur.entries.get(seg)
      if (existing === undefined) {
        const nt = newTable(curPath, false)
        cur.entries.set(seg, nt)
        cur = nt
      } else if (existing.kind === 'table') {
        cur = existing
      } else if (existing.kind === 'arrayTable') {
        cur = existing.items[existing.items.length - 1]
      } else {
        throw new ConfigError(`${joinPath(curPath)} is not a table`)
      }
    }
    const lastSeg = nameParts[nameParts.length - 1]
    const lastPath = curPath.concat([key(lastSeg)])
    if (cur.entries.has(lastSeg)) throw new ConfigError(`key ${joinPath(lastPath)} is defined twice`)
    const value = this.parseValue(lastPath)
    cur.entries.set(lastSeg, value)
  }

  parseHeaderLine(root) {
    this.pos++ // '['
    let isArray = false
    if (!this.atEnd() && this.line[this.pos] === '[') {
      isArray = true
      this.pos++
    }
    const nameParts = this.parseDottedName()
    this.ws()
    if (this.atEnd() || this.line[this.pos] !== ']') throw new ConfigError('unterminated table header')
    this.pos++
    if (isArray) {
      if (this.atEnd() || this.line[this.pos] !== ']') throw new ConfigError('unterminated table header')
      this.pos++
    }
    this.ws()
    if (!this.atEnd()) throw new ConfigError('trailing text after a table header')
    return this.resolveHeader(root, nameParts, isArray)
  }

  resolveHeader(root, nameParts, isArray) {
    let table = root
    let curPath = []
    for (let i = 0; i < nameParts.length; i++) {
      const seg = nameParts[i]
      const segPath = curPath.concat([key(seg)])
      const isLast = i === nameParts.length - 1
      const existing = table.entries.get(seg)
      if (!isLast) {
        if (existing === undefined) {
          const nt = newTable(segPath, false)
          table.entries.set(seg, nt)
          table = nt
        } else if (existing.kind === 'table') {
          table = existing
        } else if (existing.kind === 'arrayTable') {
          table = existing.items[existing.items.length - 1]
        } else {
          throw new ConfigError(`${joinPath(segPath)} is not a table`)
        }
      } else if (isArray) {
        let arr = existing
        if (arr === undefined) {
          arr = { kind: 'arrayTable', items: [], path: segPath }
          table.entries.set(seg, arr)
        } else if (arr.kind !== 'arrayTable') {
          throw new ConfigError(`${joinPath(segPath)} is not an array of tables`)
        }
        const elemPath = segPath.concat([idx(arr.items.length)])
        const elem = newTable(elemPath, true)
        arr.items.push(elem)
        return elem
      } else {
        if (existing === undefined) {
          const nt = newTable(segPath, true)
          table.entries.set(seg, nt)
          return nt
        } else if (existing.kind === 'table') {
          if (existing.headerDeclared) throw new ConfigError(`table ${joinPath(segPath)} is defined twice`)
          existing.headerDeclared = true
          return existing
        } else {
          throw new ConfigError(`${joinPath(segPath)} is not a table`)
        }
      }
      curPath = segPath
    }
    // Unreachable: nameParts always has at least one segment.
    return table
  }

  parseAssignLine(current) {
    const nameParts = this.parseDottedName()
    this.ws()
    if (this.atEnd() || this.line[this.pos] !== '=') throw new ConfigError('expected key = value')
    this.pos++
    this.assign(current, nameParts)
    this.ws()
    if (!this.atEnd()) throw new ConfigError('trailing text after a value')
  }
}

/** Returns true when the line carries nothing but whitespace and/or a comment. */
export function isBlankLine(line) {
  const p = new LineParser(line)
  p.ws()
  return p.atEnd()
}

export function parseLine(line, root, current) {
  const p = new LineParser(line)
  p.ws()
  if (p.line[p.pos] === '[') return p.parseHeaderLine(root)
  p.parseAssignLine(current)
  return current
}

export { newTable }
"}

