function sortedKeys(table) {
  return [...table.entries.keys()].sort(codePointCompare)
}

function normalizeInteger(raw) {
  let s = raw.replace(/_/g, '')
  if (s[0] === '+') s = s.slice(1)
  return BigInt(s).toString()
}

function normalizeFloat(raw) {
  const s = raw.replace(/_/g, '')
  return JSON.stringify(Number(s))
}

function toJSON(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const lines = keys.map((k) => `${padIn}${JSON.stringify(k)}: ${toJSON(node.entries.get(k), indent + 1)}`)
      return `{\n${lines.join(',\n')}\n${pad}}`
    }
    case 'arrayTable':
    case 'array': {
      if (node.items.length === 0) return '[]'
      const lines = node.items.map((it) => `${padIn}${toJSON(it, indent + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return normalizeInteger(node.raw)
    case 'float':
      return normalizeFloat(node.raw)
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function formatJSON(root) {
  return `${toJSON(root, 0)}\n`
}

