  if (node.kind === 'arrayTable' || node.kind === 'array') return 'array'
  return node.kind
}

function collectKeys(node, path, out) {
  out.push(`${joinPath(path)} ${typeName(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) collectKeys(node.entries.get(k), path.concat([key(k)]), out)
  } else if (node.kind === 'arrayTable' || node.kind === 'array') {
    node.items.forEach((it, i) => collectKeys(it, path.concat([idx(i)]), out))
  }
}

export function formatKeys(root) {
  const out = []
  for (const k of sortedKeys(root)) collectKeys(root.entries.get(k), [key(k)], out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
