 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parseDocument } from './document.js'
import { formatJSON, formatKeys } from './output.js'
import { DocError } from './errors.js'

function main() {
  const mode = process.argv[2]
  if (mode !== 'json' && mode !== 'keys') {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')

  let root
  try {
    root = parseDocument(input)
  } catch (e) {
    if (e instanceof DocError) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  const output = mode === 'json' ? formatJSON(root) : formatKeys(root)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

