const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_FRAC_RE = /^[+-]?[0-9]+(_[0-9]+)*\.[0-9]+(_[0-9]+)*([eE][+-]?[0-9]+(_[0-9]+)*)?$/
const FLOAT_EXP_RE = /^[+-]?[0-9]+(_[0-9]+)*[eE][+-]?[0-9]+(_[0-9]+)*$/
// A bare value token stops at whitespace and structural delimiters, and at
// `;` (which always starts a comment); `#` is deliberately excluded so a `#`
// glued directly onto the token is swallowed into it, per the spec's carve-out.
const BARE_STOP = new Set([' ', '\t', ',', ']', '}', ';'])

function newTable(path, headerDeclared) {
  return { kind: 'table', entries: new Map(), headerDeclared, path }

